
-- Copiando estrutura para tabela dbsdc.users
CREATE TABLE IF NOT EXISTS `users` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'Identificador do Usuário',
  `name` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Noma do Usuário',
  `email` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Email do Usuário',
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `password` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Senha do Usuário',
  `ativo` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Situação do Usuário',
  `remember_token` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `id_user_cedec` int DEFAULT NULL COMMENT 'Identificador Cedec_usuario',
  `cpf` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'CPF do Usuario',
  `tipo` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'convidado' COMMENT 'Tipo de usuario Interno Externo',
  `sub_tipo` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'membro',
  `municipio_id` int NOT NULL COMMENT 'Identificador do Municipio',
  `api_token` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `login` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `id_empdor` int DEFAULT NULL COMMENT 'Id Usuário Empreendedor',
  `email_alt` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `telefone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `masp` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `orgao_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_email_unique` (`email`),
  UNIQUE KEY `cpf` (`cpf`),
  KEY `fk_users_orgao_id` (`orgao_id`),
  CONSTRAINT `fk_users_orgao_id` FOREIGN KEY (`orgao_id`) REFERENCES `inventario_orgaos` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=1134 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

